SELECT stock_id AS stockId, buy_count AS count, DATE_FORMAT(buy_date, '%Y-%m-%d') AS date FROM buy_records WHERE stock_id IN
#{stockId}
ORDER BY buy_date ASC, created_at ASC

SELECT stock_id AS stockId, sell_count AS count, DATE_FORMAT(sell_date, '%Y-%m-%d') AS date FROM sell_records WHERE stock_id IN
#{stockId}
ORDER BY sell_date ASC, created_at ASC
